(function(){
'use strict';
const $=id=>document.getElementById(id),catalogKey='declic-library-v1',builtins=DEClic_BUILTINS;
let custom=[],storageIssue=false,deleteTarget=null,uid=0;
try{const saved=JSON.parse(localStorage.getItem(catalogKey));if(saved!==null){if(!Array.isArray(saved)||saved.length>50)throw new Error();custom=saved.map(q=>{if(!q||typeof q.id!=='string'||!/^custom-[a-zA-Z0-9_-]+$/.test(q.id))throw new Error();return {...QuizCatalog.normalizeQuiz(q),id:q.id,storageKey:'declic-'+q.id+'-v1',symbol:q.title.trim().slice(0,1).toUpperCase(),custom:true};});if(new Set(custom.map(q=>q.id)).size!==custom.length)throw new Error();}}catch{storageIssue=true;}
const all=()=>[...builtins,...custom];
function notify(message,error=false){$('library-message').textContent=message;$('library-message').classList.toggle('error',error);}
function persist(next){try{localStorage.setItem(catalogKey,JSON.stringify(next));custom=next;storageIssue=false;return true;}catch{notify('Le navigateur ne permet pas d’enregistrer ce quiz. Exporte tes quiz ou libère de l’espace, puis réessaie.',true);return false;}}
function node(tag,className,text){const e=document.createElement(tag);if(className)e.className=className;if(text!==undefined)e.textContent=text;return e;}
function download(quiz){const blob=new Blob([JSON.stringify({title:quiz.title,description:quiz.description,cards:quiz.cards},null,2)],{type:'application/json;charset=utf-8'});const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=quiz.title.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'-').toLowerCase()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Quiz exporté. Tu peux l’importer sur un autre appareil. La progression reste propre à ce navigateur.');}
function renderLibrary(){const quizzes=all(),query=$('quiz-search').value.trim().toLocaleLowerCase('fr');$('library-count').textContent=quizzes.length+' matières · '+quizzes.reduce((n,q)=>n+q.cards.length,0)+' questions';const container=$('quiz-list');container.replaceChildren();let visible=0;
 for(const q of quizzes){if(!q.title.toLocaleLowerCase('fr').includes(query))continue;visible++;const mastered=DeclicQuiz.progress(q),pct=Math.round(mastered/q.cards.length*100);const article=node('article','subject-card'),top=node('div','subject-top'),symbol=node('span','subject-symbol',q.symbol||q.title[0]);symbol.setAttribute('aria-hidden','true');top.append(symbol,node('span','subject-kind',q.custom?'PERSONNEL':'COURS'));article.appendChild(top);const h=node('h2','',q.title);article.append(h,node('p','subject-description',q.description));article.append(node('p','subject-meta',q.cards.length+' questions · '+new Set(q.cards.map(c=>c.chapter)).size+' chapitres'));const meter=node('div','subject-meter');meter.setAttribute('role','progressbar');meter.setAttribute('aria-label','Progression en '+q.title);meter.setAttribute('aria-valuemin','0');meter.setAttribute('aria-valuemax','100');meter.setAttribute('aria-valuenow',String(pct));const fill=node('div');fill.style.width=pct+'%';meter.appendChild(fill);article.append(meter,node('p','subject-progress',mastered+' / '+q.cards.length+' réussies · '+pct+' %'));
 const actions=node('div','subject-actions'),start=node('button','btn primary',mastered?'Continuer ↗':'Réviser ↗');start.type='button';start.setAttribute('aria-label','Réviser '+q.title);start.onclick=()=>openQuiz(q.id);const exportBtn=node('button','text-btn','Exporter');exportBtn.type='button';exportBtn.setAttribute('aria-label','Exporter '+q.title);exportBtn.onclick=()=>download(q);actions.append(start,exportBtn);if(q.custom){const del=node('button','text-btn delete-btn','Supprimer');del.type='button';del.setAttribute('aria-label','Supprimer '+q.title);del.onclick=()=>{deleteTarget=q;$('delete-name').textContent=q.title;$('delete-dialog').showModal();};actions.appendChild(del);}article.appendChild(actions);container.appendChild(article);}
 $('no-results').classList.toggle('hidden',visible!==0);if(!query){const add=node('button','add-subject'),plus=node('span','add-plus','+');add.type='button';add.append(plus,node('strong','','Une nouvelle matière'),node('span','','Ajoute tes questions et leurs corrections'));add.onclick=()=>openBuilder();container.appendChild(add);}
}
function showLibrary(){DeclicQuiz.leave();$('quiz-screen').classList.add('hidden');$('library-screen').classList.remove('hidden');$('home-button').classList.add('hidden');document.title='Déclic · Mes quiz';renderLibrary();$('library-title').focus();}
function openQuiz(id){const quiz=all().find(q=>q.id===id);if(!quiz)return;$('library-screen').classList.add('hidden');$('quiz-screen').classList.remove('hidden');$('home-button').classList.remove('hidden');DeclicQuiz.open(quiz);$('quiz-subject').focus();window.scrollTo({top:0,behavior:'smooth'});}
function addRow(card={}){const row=node('fieldset','question-row'),num=++uid;row.appendChild(node('legend','','Question '+($('question-rows').children.length+1)));
 for(const [name,label,type,value] of [['question','Question','textarea',card.question||''],['answer','Correction attendue','textarea',card.answer||''],['chapter','Chapitre (facultatif)','input',card.chapter||'']]){const field=node('div','builder-field'),l=node('label','',label),input=node(type);input.id='edit-'+name+'-'+num;input.dataset.field=name;input.value=value;if(type==='textarea'){input.rows=name==='question'?2:3;input.maxLength=name==='question'?10000:40000;}else{input.type='text';input.maxLength=150;}l.htmlFor=input.id;field.append(l,input);row.appendChild(field);}
 const remove=node('button','text-btn','Retirer cette question');remove.type='button';remove.onclick=()=>{row.remove();if(!$('question-rows').children.length)addRow();Array.from($('question-rows').children).forEach((r,i)=>r.querySelector('legend').textContent='Question '+(i+1));};row.appendChild(remove);$('question-rows').appendChild(row);return row;}
function openBuilder(data){$('builder-title').value=data?.title||'';$('builder-error').textContent='';$('question-rows').replaceChildren();uid=0;for(const card of data?.cards||[{}])addRow(card);$('builder-dialog').showModal();$('builder-title').focus();}
function saveBuilder(e){e.preventDefault();try{if(custom.length>=50)throw new Error('Tu peux ajouter jusqu’à 50 quiz personnels. Exporte puis retire un ancien quiz pour en ajouter un autre.');const rows=Array.from($('question-rows').children).map(row=>Object.fromEntries(Array.from(row.querySelectorAll('[data-field]')).map(input=>[input.dataset.field,input.value]))).filter(c=>c.question.trim()||c.answer.trim());const parsed=QuizCatalog.normalizeQuiz({title:$('builder-title').value,cards:rows});const id='custom-'+crypto.randomUUID(),quiz={...parsed,id,storageKey:'declic-'+id+'-v1',symbol:parsed.title[0].toUpperCase(),custom:true};if(!persist([...custom,quiz])){$('builder-error').textContent='Enregistrement impossible : vérifie l’espace disponible dans ton navigateur.';return;}$('builder-dialog').close();$('quiz-search').value='';renderLibrary();notify('« '+quiz.title+' » a été ajouté à ta bibliothèque.');}catch(error){$('builder-error').textContent=error.message;}}
async function importFile(){const file=$('import-file').files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('Le fichier est trop volumineux (5 Mo maximum).');let data;try{data=JSON.parse(await file.text());}catch{throw new Error('Ce fichier ne contient pas un quiz JSON valide. Utilise un fichier exporté depuis Déclic.');}const quiz=QuizCatalog.normalizeQuiz(data,file.name.replace(/\.json$/i,''));openBuilder(quiz);}catch(error){notify(error.message,true);}finally{$('import-file').value='';}}
$('home-button').onclick=showLibrary;$('add-quiz').onclick=()=>openBuilder();$('quiz-search').addEventListener('input',renderLibrary);$('import-quiz').onclick=()=>$('import-file').click();$('import-file').addEventListener('change',importFile);$('add-question').onclick=()=>{const row=addRow();row.scrollIntoView({behavior:'smooth',block:'nearest'});row.querySelector('textarea').focus();};$('builder-form').addEventListener('submit',saveBuilder);$('cancel-builder').onclick=()=>$('builder-dialog').close();$('cancel-delete').onclick=()=>$('delete-dialog').close();$('confirm-delete').onclick=()=>{if(deleteTarget&&persist(custom.filter(q=>q.id!==deleteTarget.id))){try{localStorage.removeItem(deleteTarget.storageKey);}catch{}$('delete-dialog').close();deleteTarget=null;renderLibrary();notify('Le quiz personnel a été supprimé.');}};
renderLibrary();if(storageIssue)notify('La sauvegarde de tes quiz personnels est illisible ou inaccessible. Aucun quiz enregistré n’a été supprimé. Exporte tes fichiers avant toute réinitialisation.',true);
globalThis.DeclicLibrary={all,openQuiz,showLibrary,renderLibrary,openBuilder};
})();
